//! Iteration 4 architecture proofs: CLI hub + Structure/Storage tree.
use std::fs;
use std::path::PathBuf;
use std::process::Command;
use tempfile::TempDir;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn bin() -> PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("failed to run residual binary")
}

fn read(rel: &str) -> String {
    fs::read_to_string(root().join(rel)).unwrap_or_else(|e| panic!("read {}: {}", rel, e))
}

fn src_exists(rel: &str) -> bool {
    root().join("src").join(rel).is_file()
}

// --- module tree ---

#[test]
fn iter4_module_tree_exists() {
    let required = [
        "cli.rs",
        "skills/mod.rs",
        "skills/personas.rs",
        "skills/research.rs",
        "skills/phases.rs",
        "skills/installer.rs",
        "verification/mod.rs",
        "verification/git_hook.rs",
        "verification/config.rs",
        "structure/mod.rs",
        "structure/analysis/mod.rs",
        "structure/analysis/nkp.rs",
        "structure/analysis/tag_scan.rs",
        "structure/analysis/force.rs",
        "structure/analysis/purposes.rs",
        "structure/analysis/stressors.rs",
        "structure/analysis/attractors.rs",
        "structure/analysis/residues.rs",
        "structure/definition/mod.rs",
        "structure/definition/lexicon.rs",
        "structure/definition/components.rs",
        "structure/definition/iterations.rs",
        "storage/mod.rs",
        "storage/config.rs",
        "storage/format.rs",
        "storage/integrity/mod.rs",
        "storage/integrity/sessions.rs",
        "storage/integrity/migration.rs",
    ];
    let missing: Vec<_> = required.iter().copied().filter(|p| !src_exists(p)).collect();
    assert!(
        missing.is_empty(),
        "missing iter4 modules: {}",
        missing.join(", ")
    );
}

#[test]
fn personas_and_research_are_not_fused() {
    assert!(src_exists("skills/personas.rs"));
    assert!(src_exists("skills/research.rs"));
    let personas = read("src/skills/personas.rs");
    let research = read("src/skills/research.rs");
    assert!(
        !personas.contains("pub use crate::skills::research")
            && !research.contains("pub use crate::skills::personas"),
        "Personas and Research must remain distinct modules"
    );
    assert!(
        !root().join("src/skills/evidence.rs").exists() && !root().join("src/evidence").exists(),
        "do not fuse personas + research into evidence"
    );
}

#[test]
fn two_configs_are_split() {
    let vcfg = read("src/verification/config.rs");
    let scfg = read("src/storage/config.rs");
    assert!(
        vcfg.contains("super_strict") || vcfg.contains("super-strict"),
        "verification-config owns super-strict"
    );
    assert!(
        vcfg.contains("token_warn"),
        "verification-config owns token_warn"
    );
    assert!(
        !vcfg.contains("format_version") && !vcfg.contains("change_detection"),
        "verification-config must not own format version / change_detection"
    );
    assert!(
        scfg.contains("format_version") || scfg.contains("format-version"),
        "storage-config owns format version"
    );
    assert!(
        scfg.contains("change_detection") || scfg.contains("change-detection"),
        "storage-config owns change_detection"
    );
    assert!(
        !scfg.contains("super_strict") && !scfg.contains("super-strict"),
        "storage-config must not own super-strict"
    );
}

// --- CLI process lives beside actions, not in a shared preamble ---

#[test]
fn cli_process_lives_beside_actions() {
    let r = root();
    for banned in [
        "src/process.rs",
        "src/fluency.rs",
        "src/preamble.rs",
        "src/cli/process.rs",
        "src/cli/fluency.rs",
        "src/cli/preamble.rs",
        "src/cli/process.md",
    ] {
        assert!(
            !r.join(banned).exists(),
            "process/fluency must not live in shared module {}",
            banned
        );
    }
    let cli = read("src/cli.rs");
    assert!(
        !cli.contains("mod process")
            && !cli.contains("mod fluency")
            && !cli.contains("mod preamble")
            && !cli.contains("include_str!(\"process")
            && !cli.contains("include_str!(\"fluency")
            && !cli.contains("include_str!(\"preamble"),
        "cli.rs must not load a shared process/fluency preamble module"
    );
    // Process text is embedded next to clap actions (about / long_about).
    let has_per_action_process = cli.contains("long_about")
        || cli.matches("/// Process:").count() >= 3
        || cli.matches("Process:").count() >= 3;
    assert!(
        has_per_action_process,
        "expected process guidance beside individual clap actions (long_about or /// Process:)"
    );
}

// --- installer check-install ---

#[test]
fn installer_check_install_subcommand() {
    let dir = TempDir::new().unwrap();
    let nested = run(&dir, &["skill", "check-install", "--help"]);
    let nested_out = format!(
        "{}{}",
        String::from_utf8_lossy(&nested.stdout),
        String::from_utf8_lossy(&nested.stderr)
    );
    assert!(
        nested.status.success(),
        "residual skill check-install --help should succeed: {}",
        nested_out
    );
    assert!(
        nested_out.contains("check-install") || nested_out.contains("check_install"),
        "help should mention check-install, got: {}",
        nested_out
    );

    // Old hyphenated alias still works.
    let alias = run(&dir, &["skill-check", "--help"]);
    assert!(
        alias.status.success(),
        "skill-check alias should remain: {}",
        String::from_utf8_lossy(&alias.stderr)
    );
}

