        "personas",
        "research",
        "phases",
        "installer",
        "verification",
        "git-hook",
        "verification-config",
        "structure",
        "analysis",
        "tag-scan",
        "force-schema",
        "purposes-schema",
        "stressors-schema",
        "attractors-schema",
        "residues-schema",
