//! Structure — filter subsets (parallel architecture sets) and sort/group.
//! Default group key = attractor. Grouping stays flexible; not creation order.

use std::collections::BTreeMap;

pub mod analysis;
pub mod definition;

pub trait AttractorKeyed {
    fn attractor_id(&self) -> &str;
    fn record_id(&self) -> &str;
}

/// Group records by attractor id (sorted keys, not insertion/creation order).
pub fn group_by_attractor<T: AttractorKeyed + Clone>(
    items: &[T],
) -> BTreeMap<String, Vec<T>> {
    let mut map: BTreeMap<String, Vec<T>> = BTreeMap::new();
    for item in items {
        map.entry(item.attractor_id().to_string())
            .or_default()
            .push(item.clone());
    }
    map
}

/// Sort by attractor, then record id — never rely on creation order.
pub fn sort_by_attractor<T: AttractorKeyed>(items: &mut [T]) {
    items.sort_by(|a, b| {
        a.attractor_id()
            .cmp(b.attractor_id())
            .then_with(|| a.record_id().cmp(b.record_id()))
    });
}

/// Filter a parallel architecture set by name.
pub fn filter_architecture_set<'a, T>(
    items: &'a [T],
    set: &str,
    set_of: impl Fn(&T) -> &str,
) -> Vec<&'a T> {
    items.iter().filter(|i| set_of(i) == set).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct Rec {
        id: &'static str,
        attractor_id: &'static str,
    }

    impl AttractorKeyed for Rec {
        fn attractor_id(&self) -> &str {
            self.attractor_id
        }
        fn record_id(&self) -> &str {
            self.id
        }
    }

    #[test]
    fn structure_groups_by_attractor() {
        let records = vec![
            Rec {
                id: "P-02",
                attractor_id: "A-02",
            },
            Rec {
                id: "P-01",
                attractor_id: "A-01",
            },
            Rec {
                id: "S-01",
                attractor_id: "A-01",
            },
        ];
        let grouped = group_by_attractor(&records);
        let keys: Vec<&String> = grouped.keys().collect();
        assert_eq!(
            keys.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
            vec!["A-01", "A-02"],
            "default group is attractor, sorted, not creation order"
        );
        assert_eq!(grouped["A-01"].len(), 2);
        assert_eq!(grouped["A-02"].len(), 1);

        let mut sorted = records.clone();
        sort_by_attractor(&mut sorted);
        assert_eq!(
            sorted.iter().map(|r| r.id).collect::<Vec<_>>(),
            vec!["P-01", "S-01", "P-02"]
        );
    }
}

//! Storage.Config — whole-application config; v3 TOML.
//! Owns format_version + change_detection. Does **not** own super-strict / token_warn
//! (those live in verification::config).

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};

fn default_format_version() -> String {
    "v3".to_string()
}
fn default_change_detection() -> bool {
    true
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StorageConfig {
    #[serde(default = "default_format_version")]
    pub format_version: String,
    #[serde(default = "default_change_detection")]
    pub change_detection: bool,
}

impl Default for StorageConfig {
    fn default() -> Self {
        Self {
            format_version: default_format_version(),
            change_detection: default_change_detection(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct V3Document {
    #[serde(default = "default_format_version")]
    format_version: String,
    #[serde(default)]
    storage: StorageSection,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct StorageSection {
    #[serde(default = "default_change_detection")]
    change_detection: bool,
}

/// Parse a v3 TOML document. Verification keys may be present in the file but
/// are ignored here — they belong to verification-config.
pub fn parse_v3(toml_str: &str) -> Result<StorageConfig> {
    let doc: V3Document =
        toml::from_str(toml_str).with_context(|| "parse storage v3 TOML")?;
    Ok(StorageConfig {
        format_version: doc.format_version,
        change_detection: doc.storage.change_detection,
    })
}

pub fn render_v3(storage: &StorageConfig) -> String {
    format!(
        "# residual v3 configuration\nformat_version = \"{}\"\n\n[storage]\nchange_detection = {}\n\n[verification]\nsuper_strict = true\ntoken_warn = 1000\n",
        storage.format_version, storage.change_detection
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn storage_config_parses_v3_toml() {
        let raw = r#"
format_version = "v3"

[storage]
change_detection = false

[verification]
super_strict = true
token_warn = 500
"#;
        let cfg = parse_v3(raw).unwrap();
        assert_eq!(cfg.format_version, "v3");
        assert!(!cfg.change_detection);
        let debug = format!("{:?}", cfg);
        assert!(
            !debug.contains("super_strict") && !debug.contains("token_warn"),
            "storage-config must not hold verification keys, got {debug}"
        );
    }
}

//! Format — current multi-file CSV; round-trip structure.analysis.* and
//! structure.definition.* ↔ CSV.

use anyhow::Result;
use std::path::Path;

use crate::structure::analysis::force::{Force, ForceKind};
use crate::structure::definition::lexicon::Term;

const FORCES_HEADER: &str = "id,kind,naive_change,outcomes,description,attractor_id";
const LEXICON_HEADER: &str = "term,definition,domain,aliases";

pub fn write_forces(residual_dir: &Path, forces: &[Force]) -> Result<()> {
    let path = residual_dir.join("forces.csv");
    let mut buf = FORCES_HEADER.to_string();
    buf.push('\n');
    for f in forces {
        let kind = match f.kind {
            ForceKind::Purpose => "purpose",
            ForceKind::Stressor => "stressor",
        };
        let outcomes = f.outcomes.join("|");
        let mut row = Vec::new();
        {
            let mut wtr = csv::WriterBuilder::new()
                .has_headers(false)
                .from_writer(&mut row);
            wtr.write_record(&[
                f.id.as_str(),
                kind,
                f.naive_change.as_str(),
                outcomes.as_str(),
                f.description.as_str(),
                f.attractor_id.as_str(),
            ])?;
            wtr.flush()?;
        }
        buf.push_str(std::str::from_utf8(&row)?);
    }
    std::fs::write(path, buf)?;
    Ok(())
}

pub fn read_forces(residual_dir: &Path) -> Result<Vec<Force>> {
    let path = residual_dir.join("forces.csv");
    if !path.exists() {
        return Ok(vec![]);
    }
    let mut rdr = csv::ReaderBuilder::new()
        .has_headers(true)
        .from_path(&path)?;
    let mut out = Vec::new();
    for rec in rdr.records() {
        let rec = rec?;
        let kind = match rec.get(1).unwrap_or("").to_lowercase().as_str() {
            "purpose" => ForceKind::Purpose,
            _ => ForceKind::Stressor,
        };
        let outcomes = rec
            .get(3)
            .unwrap_or("")
            .split('|')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect();
        out.push(Force {
            id: rec.get(0).unwrap_or("").to_string(),
            kind,
            naive_change: rec.get(2).unwrap_or("").to_string(),
            outcomes,
            description: rec.get(4).unwrap_or("").to_string(),
            attractor_id: rec.get(5).unwrap_or("").to_string(),
        });
    }
    Ok(out)
}

pub fn write_lexicon(residual_dir: &Path, terms: &[Term]) -> Result<()> {
    let path = residual_dir.join("lexicon.csv");
    let mut buf = LEXICON_HEADER.to_string();
    buf.push('\n');
    for t in terms {
        let mut row = Vec::new();
        {
            let mut wtr = csv::WriterBuilder::new()
                .has_headers(false)
                .from_writer(&mut row);
            wtr.write_record(&[
                t.term.as_str(),
                t.definition.as_str(),
                t.domain.as_str(),
                t.aliases.as_str(),
            ])?;
            wtr.flush()?;
        }
        buf.push_str(std::str::from_utf8(&row)?);
    }
    std::fs::write(path, buf)?;
    Ok(())
}

pub fn read_lexicon(residual_dir: &Path) -> Result<Vec<Term>> {
    let path = residual_dir.join("lexicon.csv");
    if !path.exists() {
        return Ok(vec![]);
    }
    let mut rdr = csv::ReaderBuilder::new()
        .has_headers(true)
        .from_path(&path)?;
    let mut out = Vec::new();
    for rec in rdr.deserialize() {
        out.push(rec?);
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn format_roundtrips_force_and_lexicon() {
        let dir = tempdir().unwrap();
        let force = Force::stressor(
            "S-01",
            "install stubs so binary owns methodology",
            vec!["skill sessions follow binary methodology".into()],
        );
        let term = Term {
            term: "residue".into(),
            definition: "force + component mapping".into(),
            domain: "core".into(),
            aliases: "residual".into(),
        };
        write_forces(dir.path(), &[force.clone()]).unwrap();
        write_lexicon(dir.path(), &[term.clone()]).unwrap();
        let forces = read_forces(dir.path()).unwrap();
        let terms = read_lexicon(dir.path()).unwrap();
        assert_eq!(forces, vec![force]);
        assert_eq!(terms, vec![term]);
    }
}

//! Sessions — locks, change-detection hash, append logic, flag when diff/--force is needed.

use anyhow::{bail, Context, Result};
use std::collections::BTreeMap;
use std::fs;
use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const LOCK_NAME: &str = ".session.lock";
const SNAPSHOT_NAME: &str = ".storage-hashes";
const DEFAULT_TTL_SECS: u64 = 30;

#[derive(Debug)]
pub struct SessionLock {
    path: PathBuf,
}

impl SessionLock {
    pub fn path(residual_dir: &Path) -> PathBuf {
        residual_dir.join(LOCK_NAME)
    }

    pub fn acquire(residual_dir: &Path) -> Result<Self> {
        fs::create_dir_all(residual_dir)?;
        let path = Self::path(residual_dir);
        if path.exists() {
            if is_stale(&path, DEFAULT_TTL_SECS)? {
                let _ = fs::remove_file(&path);
            } else {
                bail!(
                    "session lock held at {} — another mutation in progress",
                    path.display()
                );
            }
        }
        let pid = std::process::id();
        let now = now_secs();
        fs::write(&path, format!("pid={}\nacquired={}\n", pid, now))
            .with_context(|| format!("write lock {}", path.display()))?;
        Ok(Self { path })
    }

    pub fn release(self) -> Result<()> {
        if self.path.exists() {
            fs::remove_file(&self.path)
                .with_context(|| format!("release lock {}", self.path.display()))?;
        }
        Ok(())
    }
}

impl Drop for SessionLock {
    fn drop(&mut self) {
        if self.path.exists() {
            let _ = fs::remove_file(&self.path);
        }
    }
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs()
}

fn is_stale(path: &Path, ttl_secs: u64) -> Result<bool> {
    let contents = fs::read_to_string(path)?;
    let acquired = contents
        .lines()
        .find_map(|l| l.strip_prefix("acquired=").and_then(|v| v.parse::<u64>().ok()))
        .unwrap_or(0);
    Ok(now_secs().saturating_sub(acquired) > ttl_secs)
}

pub fn managed_rel_paths(residual_dir: &Path) -> Result<Vec<String>> {
    let mut paths = vec![
        "stressors.csv".to_string(),
        "purposes.csv".to_string(),
        "attractors.csv".to_string(),
        "terminology.csv".to_string(),
        "forces.csv".to_string(),
        "lexicon.csv".to_string(),
        "residues.csv".to_string(),
        "components.csv".to_string(),
        "config.toml".to_string(),
    ];
    for sub in &["personas", "iterations", "research"] {
        let dir = residual_dir.join(sub);
        if !dir.is_dir() {
            continue;
        }
        let mut entries: Vec<_> = fs::read_dir(&dir)?
            .filter_map(|e| e.ok())
            .filter(|e| e.path().is_file())
            .collect();
        entries.sort_by_key(|e| e.file_name());
        for e in entries {
            let name = e.file_name().to_string_lossy().into_owned();
            paths.push(format!("{}/{}", sub, name));
        }
    }
    paths.sort();
    Ok(paths)
}

fn hash_bytes(data: &[u8]) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    data.hash(&mut hasher);
    hasher.finish()
}

pub fn current_hashes(residual_dir: &Path) -> Result<BTreeMap<String, String>> {
    let mut map = BTreeMap::new();
    for rel in managed_rel_paths(residual_dir)? {
        let path = residual_dir.join(&rel);
        let digest = if path.exists() {
            let bytes = fs::read(&path).with_context(|| format!("read {}", path.display()))?;
            format!("{:016x}", hash_bytes(&bytes))
        } else {
            "missing".to_string()
        };
        map.insert(rel, digest);
    }
    Ok(map)
}

pub fn snapshot_path(residual_dir: &Path) -> PathBuf {
    residual_dir.join(SNAPSHOT_NAME)
}

pub fn write_snapshot(residual_dir: &Path) -> Result<()> {
    let hashes = current_hashes(residual_dir)?;
    let mut body = String::from("# storage integrity change-detection snapshot\n");
    for (path, digest) in &hashes {
        body.push_str(&format!("{}={}\n", path, digest));
    }
    fs::write(snapshot_path(residual_dir), body)
        .with_context(|| format!("write {}", snapshot_path(residual_dir).display()))?;
    Ok(())
}

pub fn load_snapshot(residual_dir: &Path) -> Result<Option<BTreeMap<String, String>>> {
    let path = snapshot_path(residual_dir);
    if !path.exists() {
        return Ok(None);
    }
    let text = fs::read_to_string(&path)?;
    let mut map = BTreeMap::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            map.insert(k.to_string(), v.to_string());
        }
    }
    Ok(Some(map))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DriftReport {
    pub drifted: Vec<String>,
    pub added: Vec<String>,
    pub removed: Vec<String>,
}

impl DriftReport {
    pub fn is_clean(&self) -> bool {
        self.drifted.is_empty() && self.added.is_empty() && self.removed.is_empty()
    }
}

pub fn detect_drift(residual_dir: &Path) -> Result<DriftReport> {
    let Some(baseline) = load_snapshot(residual_dir)? else {
        return Ok(DriftReport {
            drifted: vec![],
            added: vec![],
            removed: vec![],
        });
    };
    let current = current_hashes(residual_dir)?;
    let mut drifted = Vec::new();
    let mut added = Vec::new();
    let mut removed = Vec::new();

    for (path, digest) in &current {
        match baseline.get(path) {
            Some(prev) if prev != digest => drifted.push(path.clone()),
            Some(_) => {}
            None => added.push(path.clone()),
        }
    }
    for path in baseline.keys() {
        if !current.contains_key(path) {
            removed.push(path.clone());
        }
    }
    Ok(DriftReport {
        drifted,
        added,
        removed,
    })
}

pub struct SessionGuard {
    _lock: SessionLock,
    residual_dir: PathBuf,
}

/// Begin a mutating session. On snapshot drift, require `--force` (or inspect diff).
pub fn begin_mutation(residual_dir: &Path, force: bool) -> Result<SessionGuard> {
    let lock = SessionLock::acquire(residual_dir)?;
    let drift = detect_drift(residual_dir)?;
    if !drift.is_clean() && !force {
        let mut parts = Vec::new();
        if !drift.drifted.is_empty() {
            parts.push(format!("changed: {}", drift.drifted.join(", ")));
        }
        if !drift.added.is_empty() {
            parts.push(format!("added: {}", drift.added.join(", ")));
        }
        if !drift.removed.is_empty() {
            parts.push(format!("removed: {}", drift.removed.join(", ")));
        }
        bail!(
            "residual data drifted outside this session ({}); pass --force to overwrite or inspect diff",
            parts.join("; ")
        );
    }
    Ok(SessionGuard {
        _lock: lock,
        residual_dir: residual_dir.to_path_buf(),
    })
}

impl SessionGuard {
    pub fn commit(self) -> Result<()> {
        write_snapshot(&self.residual_dir)?;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn sessions_require_force_flag_on_drift() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        fs::create_dir_all(&residual).unwrap();
        fs::write(
            residual.join("terminology.csv"),
            "term,definition,domain,related_terms\n",
        )
        .unwrap();
        fs::write(residual.join("config.toml"), "#\n").unwrap();
        write_snapshot(&residual).unwrap();
        assert!(detect_drift(&residual).unwrap().is_clean());

        let mut terms = fs::read_to_string(residual.join("terminology.csv")).unwrap();
        terms.push_str("smuggled,x,core,\n");
        fs::write(residual.join("terminology.csv"), terms).unwrap();

        let err = begin_mutation(&residual, false).unwrap_err();
        let msg = err.to_string();
        assert!(
            msg.contains("--force"),
            "drift without force must mention --force, got {msg}"
        );
        assert!(
            msg.contains("diff") || msg.contains("drift"),
            "drift error should flag diff, got {msg}"
        );

        let guard = begin_mutation(&residual, true).unwrap();
        guard.commit().unwrap();
        assert!(detect_drift(&residual).unwrap().is_clean());
    }
}

//! Migration — naive → v3 only for now.

use anyhow::{Context, Result};
use serde::Deserialize;

use crate::storage::config::{render_v3, StorageConfig};
use crate::verification::config::VerificationConfig;

#[derive(Debug, Clone)]
pub struct MigratedV3 {
    pub format_version: String,
    pub storage: StorageConfig,
    pub verification: VerificationConfig,
    pub toml: String,
}

#[derive(Debug, Deserialize)]
struct NaiveDocument {
    #[serde(default)]
    validation: NaiveValidation,
    #[serde(default)]
    skills: NaiveSkills,
}

#[derive(Debug, Default, Deserialize)]
struct NaiveValidation {
    #[serde(default = "default_true")]
    strict: bool,
}

#[derive(Debug, Default, Deserialize)]
struct NaiveSkills {
    #[serde(default = "default_token_warn")]
    token_warn: usize,
}

fn default_true() -> bool {
    true
}
fn default_token_warn() -> usize {
    1000
}

/// Convert naive config.toml (`[validation]` / `[skills]`) into v3 TOML.
pub fn migrate_naive_to_v3(naive_toml: &str) -> Result<MigratedV3> {
    let naive: NaiveDocument =
        toml::from_str(naive_toml).with_context(|| "parse naive config.toml")?;
    let storage = StorageConfig {
        format_version: "v3".to_string(),
        change_detection: true,
    };
    let verification = VerificationConfig {
        super_strict: naive.validation.strict,
        token_warn: naive.skills.token_warn,
    };
    let mut toml_out = render_v3(&storage);
    // render_v3 writes default verification; replace with migrated values.
    toml_out = format!(
        "# residual v3 configuration (migrated from naive)\nformat_version = \"v3\"\n\n[storage]\nchange_detection = {}\n\n[verification]\nsuper_strict = {}\ntoken_warn = {}\n",
        storage.change_detection, verification.super_strict, verification.token_warn
    );
    Ok(MigratedV3 {
        format_version: storage.format_version.clone(),
        storage,
        verification,
        toml: toml_out,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn migration_naive_to_v3() {
        let naive = "[validation]\nstrict = false\n\n[skills]\ntoken_warn = 500\n";
        let v3 = migrate_naive_to_v3(naive).unwrap();
        assert_eq!(v3.format_version, "v3");
        assert!(v3.storage.change_detection);
        assert!(!v3.verification.super_strict);
        assert_eq!(v3.verification.token_warn, 500);
        assert!(v3.toml.contains("format_version = \"v3\""));
        assert!(v3.toml.contains("[storage]"));
        assert!(v3.toml.contains("[verification]"));
        let storage_debug = format!("{:?}", v3.storage);
        assert!(
            !storage_debug.contains("super_strict") && !storage_debug.contains("token_warn"),
            "storage half of migration must not carry verification keys"
        );
    }
}

