//! Verification.Config — verification-policy keys only (super-strict, token_warn, …).
//! Does **not** own format_version / change_detection (those live in storage-config).

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};

fn default_super_strict() -> bool {
    true
}
fn default_token_warn() -> usize {
    1000
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct VerificationConfig {
    #[serde(default = "default_super_strict")]
    pub super_strict: bool,
    #[serde(default = "default_token_warn")]
    pub token_warn: usize,
}

impl Default for VerificationConfig {
    fn default() -> Self {
        Self {
            super_strict: default_super_strict(),
            token_warn: default_token_warn(),
        }
    }
}

#[derive(Debug, Deserialize)]
struct Wrapper {
    #[serde(default)]
    verification: VerificationConfig,
}

/// Parse verification-policy keys from a v3 (or verification-only) TOML document.
pub fn parse(toml_str: &str) -> Result<VerificationConfig> {
    if toml_str.contains("[verification]") {
        let w: Wrapper = toml::from_str(toml_str).with_context(|| "parse verification TOML")?;
        return Ok(w.verification);
    }
    Ok(VerificationConfig::default())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn verification_config_parses_policy_keys_only() {
        let raw = r#"
format_version = "v3"

[storage]
change_detection = true

[verification]
super_strict = false
token_warn = 42
"#;
        let cfg = parse(raw).unwrap();
        assert!(!cfg.super_strict);
        assert_eq!(cfg.token_warn, 42);
        let debug = format!("{:?}", cfg);
        assert!(
            !debug.contains("format_version") && !debug.contains("change_detection"),
            "verification-config must not hold storage keys, got {debug}"
        );
    }
}

//! Git hook install — pre-commit runs verification.

use anyhow::{Context, Result};

pub fn install() -> Result<()> {
    let cwd = std::env::current_dir().context("failed to get current directory")?;
    let mut dir = cwd.as_path();
    let git_hooks_dir = loop {
        let candidate = dir.join(".git/hooks");
        if candidate.is_dir() {
            break candidate;
        }
        match dir.parent() {
            Some(parent) => dir = parent,
            None => anyhow::bail!("could not find .git/hooks directory (not a git repository?)"),
        }
    };

    let hook_path = git_hooks_dir.join("pre-commit");
    let hook_content = r#"#!/usr/bin/env bash
# residual pre-commit hook — validates residual/ data before commit
STAGED=$(git diff --cached --name-only | grep '^residual/')

if [ -z "$STAGED" ]; then
  STRICT=$(residual config 2>/dev/null | grep 'strict' | awk '{print $3}')
  [ "$STRICT" = "false" ] && exit 0
fi

residual verify all || exit 1
"#;

    std::fs::write(&hook_path, hook_content)
        .with_context(|| format!("failed to write hook to {}", hook_path.display()))?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = std::fs::metadata(&hook_path)?.permissions();
        perms.set_mode(0o755);
        std::fs::set_permissions(&hook_path, perms)
            .with_context(|| format!("failed to set permissions on {}", hook_path.display()))?;
    }

    println!("Installed pre-commit hook to {}", hook_path.display());
    Ok(())
}

